def format_json(summary: Summary) -> str:
    """The report as a JSON object with amounts rounded to two decimals."""
    top = summary.top_product
    payload = {
        "rows": summary.rows,
        "total_revenue": round(summary.total_revenue, 2),
        "total_tax": round(summary.total_tax, 2),
        "by_region": {
            key: round(value, 2)
            for key, value in sorted(summary.by_region.items())
        },
        "by_product": {
            key: round(value, 2)
            for key, value in sorted(summary.by_product.items())
        },
        "top_product": top[0] if top is not None else None,
    }
    return json.dumps(payload, indent=2)

